import {rangePlayback} from './topic-tools.js';
import {discoveryStages,discoveryStage,discoveryExperiment} from './discovery-model.js';
const f=x=>Number(x.toFixed(4)).toString();
export function discoveryLoopBody(step=0){const m=discoveryStage(step);return '<ol class="discovery-loop">'+discoveryStages.map((s,i)=>'<li'+(i===step?' aria-current="step"':'')+'><small>'+s[0]+'</small><strong>'+s[1]+'</strong></li>').join('')+'</ol><p><strong>Stage '+(step+1)+'/6: '+m.label+'.</strong> '+m.text+'</p><p>Proposal → formal consequence → external evidence → revision. This is a conceptual loop, not an executed AI experiment or a guarantee of discovery.</p>';}
export function discoveryExperimentBody(experiment='observe',outcome=1,percent=50){const m=discoveryExperiment(experiment,outcome,percent/100);return '<div class="discovery-models"><div><strong>H<sub>A</sub>: X → Y</strong><p>X=U; Y=X</p><small>Changing X changes Y.</small></div><div><strong>H<sub>B</sub>: X ← U → Y</strong><p>X=U; Y=U</p><small>Changing X leaves U and Y unchanged.</small></div></div><div class="discovery-bars">'+[['A',m.pA],['B',m.pB]].map(([label,p])=>'<div><span>P(measured Y=1 | H'+label+', chosen test)</span><meter min="0" max="1" value="'+p+'">'+f(p)+'</meter><strong>'+f(p)+'</strong></div>').join('')+'</div><p data-result>Prior P(H<sub>A</sub>)='+f(m.prior)+'; observed measured Y='+outcome+'. Likelihoods (A, B)=('+f(m.likelihoodA)+', '+f(m.likelihoodB)+'). Posterior P(H<sub>A</sub>)=<strong>'+f(m.posterior)+'</strong>.</p><p>Prior uncertainty='+f(m.priorEntropy)+' bits; posterior uncertainty for this outcome='+f(m.posteriorEntropy)+' bits. Expected information gain before the outcome='+f(m.expectedGain)+' bits.</p><p>U is fair. Each measured Y flips with probability .1 under either hypothesis. All values are exact probabilities in two supplied toy models—not paper measurements, model predictions, or newly discovered laws.</p>';}
export function discoveryScenes(){return {
 loop:'<figure class="topic-scene" data-discovery-lab="loop"><h3>Separate invention from checking</h3><label>Discovery loop stage<input aria-label="Discovery loop stage" type="range" min="0" max="5" step="1" value="0"></label><div class="dense-actions"><button data-play>Play</button><button data-reset>Replay</button></div><div data-body>'+discoveryLoopBody()+'</div><figcaption>Original conceptual diagram. Follow the same explanation through hypothesis, consequence and test; then revise it.</figcaption></figure>',
 experiment:'<figure class="topic-scene" data-discovery-lab="experiment"><h3>Same observations, different intervention predictions</h3><label>Evidence type<select aria-label="Discovery evidence type"><option value="observe">Observe X=1</option><option value="do0">Intervene: set X=0</option><option value="do1">Intervene: set X=1</option></select></label><label>Measured outcome<select aria-label="Discovery measured outcome"><option value="1">Y=1</option><option value="0">Y=0</option></select></label><label>Prior probability of A (%)<input aria-label="Discovery prior probability" type="range" min="10" max="90" step="1" value="50"></label><div data-body>'+discoveryExperimentBody()+'</div><figcaption>Analytical illustration of testing two causal hypotheses. Selecting an outcome does not sample an environment. The experiment distinguishes supplied hypotheses; it does not invent them.</figcaption></figure>'
};}
export function mountDiscoveryScenes(article){const loop=article.querySelector('[data-discovery-lab="loop"]');if(loop)rangePlayback(article,loop,v=>{loop.querySelector('[data-body]').innerHTML=discoveryLoopBody(Math.round(v));},15000);const lab=article.querySelector('[data-discovery-lab="experiment"]');if(!lab)return;const selects=lab.querySelectorAll('select'),slider=lab.querySelector('input');const draw=()=>{lab.querySelector('[data-body]').innerHTML=discoveryExperimentBody(selects[0].value,Number(selects[1].value),Number(slider.value));};for(const select of selects)select.addEventListener('change',draw);slider.addEventListener('input',draw);}
